export interface Trial {
  accountId: string;
  expiresAt: Date;
  bannerText: string;
}

const fmt = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" });

export function createTrial({ accountId }: { accountId: string }, now: Date = new Date()): Trial {
  const expiresAt = new Date(now);
  expiresAt.setDate(expiresAt.getDate() + 14);
  return { accountId, expiresAt, bannerText: `Your trial ends on ${fmt.format(expiresAt)}` };
}

import { nanoid } from "nanoid";

export async function withRequestId(req: Request): Promise<Response> {
  const id = req.headers.get("x-request-id") ?? nanoid();
  const res = await fetch(req);
  const headers = new Headers(res.headers);
  headers.set("x-request-id", id);
  return new Response(res.body, { status: res.status, headers });
}

export interface Forecast {
  daily: { time: string[] };
}

export async function getForecast({ lat, lon }: { lat: number; lon: number }): Promise<Forecast> {
  const url = new URL("https://api.open-meteo.com/v1/forecast");
  url.searchParams.set("latitude", String(lat));
  url.searchParams.set("longitude", String(lon));
  url.searchParams.set("daily", "temperature_2m_max");
  const res = await fetch(url);
  if (!res.ok) throw new Error(`forecast failed: ${res.status}`);
  return (await res.json()) as Forecast;
}

